 assert bb['lookback_days']==v['ETH_lookback_days']==v['reversal_lookback_days']==x['reversal_lookback_days'] in [3,4] and bb['trend_lookback_days']==v['ETH_trend_lookback_days']==v['trend_filter_lookback_days']==x['trend_filter_lookback_days'] in [27,29] and bb['return_hurdle']==v['ETH_return_hurdle']==v['reversal_return_hurdle']==x['reversal_return_hurdle'] in [.02,.025] and bb['exit_buffer_fraction']==v['ETH_exit_buffer_fraction']==0
 assert v['initial_capital_usdt']==20000 and v['component_capitals_usdt']==[10000,10000] and v['raw_component_multipliers']==[1,1] and v['component_initial_entry_notionals_usdt']==[1000,3000] and v['start_utc']==p['time_boundaries']['oos_start_utc'] and v['end_utc']==p['time_boundaries']['oos_end_exclusive_utc']
